import "../css/mainPage.css";

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import logo from "../image/tybwhitelogo.png";
import logoblack from "../image/tyblogoblack.jpeg";
import esign1 from "../image/georgeEsign.jpeg";

import DashboardIcon from "@mui/icons-material/Dashboard";
import PrintIcon from "@mui/icons-material/Print";

const units = ["kg", "gms", "pcs"];

const API_BASE_URL = "http://localhost:5000";

const msme = process.env.REACT_APP_MSME;

function MainPage() {
    const navigate = useNavigate();

    // ============================================================
    // RESORT BILLING
    // ============================================================

    const [resortCustomers, setResortCustomers] = useState([]);
    const [resortProducts, setResortProducts] = useState([]);

    const [customer, setCustomer] = useState("");
    const [product, setProduct] = useState("");
    const [quantity, setQuantity] = useState(1);

    const [cart, setCart] = useState([]);

    const [billNo, setBillNo] = useState(1);
    const [balance, setBalance] = useState();

    // ============================================================
    // STORE CUSTOMER BILLING
    // ============================================================

    const [storeCustomers, setStoreCustomers] = useState([]);
    const [storeProducts, setStoreProducts] = useState([]);

    const [storeCustomerId, setStoreCustomerId] = useState("");
    const [storeCustomerName, setStoreCustomerName] = useState("");
    const [storeAddress, setStoreAddress] = useState("");

    const [storeProduct, setStoreProduct] = useState("");
    const [storeQuantity, setStoreQuantity] = useState(1);
    const [storeUnit, setStoreUnit] = useState("");
    const [storePrice, setStorePrice] = useState("");

    const [storeCart, setStoreCart] = useState([]);

    // ============================================================
    // ORDER SAVING
    // ============================================================

    const [savingOrder, setSavingOrder] = useState(false);
    const [orderSaved, setOrderSaved] = useState(false);

    const [savingStoreOrder, setSavingStoreOrder] =
        useState(false);

    const [storeOrderSaved, setStoreOrderSaved] =
        useState(false);

    // ============================================================
    // DATE
    // ============================================================

    const [isManual, setIsManual] = useState(false);
    const [selectedDate, setSelectedDate] = useState("");

    // ============================================================
    // FETCH INITIAL DATA
    // ============================================================

    useEffect(() => {
        fetchResortCustomers();
        fetchStoreCustomers();
        fetchStoreProducts();
    }, []);

    // ============================================================
    // FETCH RESORT CUSTOMERS
    // ============================================================

    const fetchResortCustomers = async () => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch resort customers"
                );
            }

            const data = await response.json();

            setResortCustomers(data);

        } catch (error) {
            console.error(
                "Error fetching resort customers:",
                error
            );
        }
    };

    // ============================================================
    // FETCH PRODUCTS FOR SELECTED RESORT
    // ============================================================

    const fetchResortProducts = async (customerId) => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers/${customerId}/products`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch products for resort"
                );
            }

            const data = await response.json();

            setResortProducts(data);

        } catch (error) {
            console.error(
                "Error fetching resort products:",
                error
            );

            setResortProducts([]);
        }
    };

    // ============================================================
    // FETCH STORE CUSTOMERS
    // ============================================================

    const fetchStoreCustomers = async () => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/store-customers`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch store customers"
                );
            }

            const data = await response.json();

            setStoreCustomers(data);

        } catch (error) {
            console.error(
                "Error fetching store customers:",
                error
            );
        }
    };

    // ============================================================
    // FETCH PRODUCTS FOR STORE CUSTOMERS
    // ============================================================

    const fetchStoreProducts = async () => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/store-customers/products`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch store products"
                );
            }

            const data = await response.json();

            setStoreProducts(data);

        } catch (error) {
            console.error(
                "Error fetching store products:",
                error
            );

            setStoreProducts([]);
        }
    };

    // ============================================================
    // RESORT CUSTOMER CHANGE
    // ============================================================

    const handleResortCustomerChange = async (e) => {
        const customerId = e.target.value;

        setCustomer(customerId);
        setProduct("");
        setQuantity(1);
        setOrderSaved(false);

        if (!customerId) {
            setResortProducts([]);
            return;
        }

        await fetchResortProducts(customerId);
    };

    // ============================================================
    // SELECTED RESORT CUSTOMER
    // ============================================================

    const selectedResortCustomer =
        resortCustomers.find(
            (c) =>
                String(c.resort_customer_id) ===
                String(customer)
        );

    // ============================================================
    // SELECTED RESORT PRODUCT / COMBO
    // ============================================================

    const selectedProduct = resortProducts.find((p) => {
        const selectedValue = product;

        if (
            p.combo_id !== null &&
            p.combo_id !== undefined
        ) {
            return (
                `combo-${p.combo_id}` ===
                selectedValue
            );
        }

        return (
            `variant-${p.product_variant_id}` ===
            selectedValue
        );
    });

    // ============================================================
    // RESORT PRICE
    // ============================================================

    const price = selectedProduct
        ? Number(selectedProduct.price)
        : 0;

    const totalPrice =
        price * Number(quantity || 0);

    // ============================================================
    // ADD RESORT ITEM
    // ============================================================

    const handleAdd = () => {
        if (!customer) {
            alert(
                "Please select a resort customer."
            );
            return;
        }

        if (!product) {
            alert("Please select a product.");
            return;
        }

        if (
            !quantity ||
            quantity <= 0
        ) {
            alert(
                "Please enter a valid quantity."
            );
            return;
        }

        if (!selectedProduct) {
            alert(
                "Product details not found."
            );
            return;
        }

        // Do not allow resort and store
        // customer items in the same bill.
        if (storeCart.length > 0) {
            alert(
                "Please create a new bill before adding resort customer items."
            );
            return;
        }

        const newItem = {
            id: Date.now(),

            resortCustomerId:
                Number(customer),

            productVariantId:
                selectedProduct.product_variant_id ??
                null,

            comboId:
                selectedProduct.combo_id ??
                null,

            product:
                selectedProduct.product_name ||
                selectedProduct.combo_name,

            packSize:
                selectedProduct.pack_size_grams ??
                null,

            quantity:
                Number(quantity),

            price:
                Number(selectedProduct.price),

            total:
                Number(selectedProduct.price) *
                Number(quantity)
        };

        setCart((prevCart) => [
            ...prevCart,
            newItem
        ]);

        setProduct("");
        setQuantity(1);
        setOrderSaved(false);
    };

    // ============================================================
    // DELETE RESORT ITEM
    // ============================================================

    const handleDelete = (id) => {
        setCart((prevCart) =>
            prevCart.filter(
                (item) => item.id !== id
            )
        );

        setOrderSaved(false);
    };

    // ============================================================
    // STORE CUSTOMER CHANGE
    // ============================================================

    const handleStoreCustomerChange = (e) => {
        const customerId = e.target.value;

        setStoreCustomerId(customerId);

        setStoreProduct("");
        setStoreQuantity(1);
        setStoreUnit("");
        setStorePrice("");

        setStoreOrderSaved(false);

        if (!customerId) {
            setStoreCustomerName("");
            setStoreAddress("");
            return;
        }

        const selectedCustomer =
            storeCustomers.find(
                (customer) =>
                    String(
                        customer.store_customer_id
                    ) === String(customerId)
            );

        if (selectedCustomer) {
            setStoreCustomerName(
                selectedCustomer.customer_name
            );

            setStoreAddress(
                selectedCustomer.address || ""
            );
        }
    };

    // ============================================================
    // SELECTED STORE PRODUCT
    // ============================================================

    const selectedStoreProduct =
        storeProducts.find(
            (p) =>
                String(p.product_id) ===
                String(storeProduct)
        );

    // ============================================================
    // STORE CUSTOMER TOTAL PRICE
    // ============================================================

    let storeTotalPrice = 0;

    if (storeUnit === "gms") {

        storeTotalPrice =
            (Number(storeQuantity || 0) /
                1000) *
            Number(storePrice || 0);

    } else {

        storeTotalPrice =
            Number(storeQuantity || 0) *
            Number(storePrice || 0);
    }

    // ============================================================
    // ADD STORE CUSTOMER ITEM
    // ============================================================

    const handleAddStoreCustomer = () => {

        if (
            !storeCustomerName.trim()
        ) {
            alert(
                "Please enter or select a store customer."
            );
            return;
        }

        if (!storeAddress.trim()) {
            alert(
                "Please enter the customer address."
            );
            return;
        }

        if (!storeProduct) {
            alert(
                "Please select a product."
            );
            return;
        }

        if (
            !storeQuantity ||
            Number(storeQuantity) <= 0
        ) {
            alert(
                "Please enter a valid quantity."
            );
            return;
        }

        if (!storeUnit) {
            alert(
                "Please select a unit."
            );
            return;
        }

        if (
            storePrice === "" ||
            Number(storePrice) < 0
        ) {
            alert(
                "Please enter a valid price."
            );
            return;
        }

        if (!selectedStoreProduct) {
            alert(
                "Product details not found."
            );
            return;
        }

        // Do not allow resort and store
        // customer items in same bill.
        if (cart.length > 0) {
            alert(
                "Please create a new bill before adding store customer items."
            );
            return;
        }

        const newItem = {
            id: Date.now(),

            productId:
                selectedStoreProduct.product_id,

            productName:
                selectedStoreProduct.product_name,

            quantity:
                Number(storeQuantity),

            unit:
                storeUnit,

            price:
                Number(storePrice),

            total:
                Number(storeTotalPrice)
        };

        setStoreCart((prevCart) => [
            ...prevCart,
            newItem
        ]);

        setStoreProduct("");
        setStoreQuantity(1);
        setStoreUnit("");
        setStorePrice("");

        setStoreOrderSaved(false);
    };

    // ============================================================
    // DELETE STORE CUSTOMER ITEM
    // ============================================================

    const handleDeleteStoreCustomer = (id) => {

        setStoreCart((prevCart) =>
            prevCart.filter(
                (item) => item.id !== id
            )
        );

        setStoreOrderSaved(false);
    };

    // ============================================================
    // NEW BILL
    // ============================================================

    const handleNewBill = () => {

        if (
            savingOrder ||
            savingStoreOrder
        ) {
            return;
        }

        // Resort
        setCustomer("");
        setProduct("");
        setQuantity(1);
        setResortProducts([]);
        setCart([]);

        // Store customer
        setStoreCustomerId("");
        setStoreCustomerName("");
        setStoreAddress("");

        setStoreProduct("");
        setStoreQuantity(1);
        setStoreUnit("");
        setStorePrice("");

        setStoreCart([]);

        setBalance(undefined);

        setOrderSaved(false);
        setStoreOrderSaved(false);

        setSavingOrder(false);
        setSavingStoreOrder(false);

        setBillNo(
            (prev) => prev + 1
        );
    };

    // ============================================================
    // SAVE RESORT ORDER
    // ============================================================

    const saveResortOrder = async () => {

        if (!customer) {
            return true;
        }

        if (cart.length === 0) {
            return true;
        }

        if (orderSaved) {
            return true;
        }

        try {

            setSavingOrder(true);

            const items =
                cart.map((item) => ({
                    productVariantId:
                        item.productVariantId,

                    comboId:
                        item.comboId,

                    quantity:
                        item.quantity,

                    // Backend converts this
                    // to total item price.
                    price:
                        item.price *
                        item.quantity
                }));

            const response =
                await fetch(
                    `${API_BASE_URL}/api/resort-customers/${customer}/orders`,
                    {
                        method: "POST",

                        headers: {
                            "Content-Type":
                                "application/json"
                        },

                        body: JSON.stringify({
                            orderDate:
                                selectedDate,

                            totalAmount:
                                Number(
                                    grandTotal
                                ),

                            items
                        })
                    }
                );

            const data =
                await response.json();

            if (!response.ok) {
                throw new Error(
                    data.message ||
                    "Failed to save order"
                );
            }

            console.log(
                "Resort order saved:",
                data
            );

            setOrderSaved(true);

            return true;

        } catch (error) {

            console.error(
                "Error saving resort order:",
                error
            );

            alert(
                "Failed to save the order. Please try again."
            );

            return false;

        } finally {

            setSavingOrder(false);
        }
    };

    // ============================================================
    // SAVE STORE CUSTOMER ORDER
    // ============================================================

    const saveStoreOrder = async () => {

        if (
            !storeCustomerName.trim()
        ) {
            return true;
        }

        if (storeCart.length === 0) {
            return true;
        }

        if (storeOrderSaved) {
            return true;
        }

        try {

            setSavingStoreOrder(true);

            const items =
                storeCart.map(
                    (item) => ({
                        productId:
                            item.productId,

                        quantity:
                            item.quantity,

                        unit:
                            item.unit,

                        /*
                         * This is the TOTAL PRICE
                         * for this particular item.
                         *
                         * Backend stores this value
                         * directly in order_item.price.
                         */
                        price:
                            item.total
                    })
                );

            const response =
                await fetch(
                    `${API_BASE_URL}/api/store-customers/orders`,
                    {
                        method: "POST",

                        headers: {
                            "Content-Type":
                                "application/json"
                        },

                        body: JSON.stringify({
                            customerName:
                                storeCustomerName.trim(),

                            address:
                                storeAddress.trim(),

                            orderDate:
                                selectedDate,

                            totalAmount:
                                Number(
                                    grandTotal
                                ),

                            items
                        })
                    }
                );

            const data =
                await response.json();

            if (!response.ok) {
                throw new Error(
                    data.message ||
                    "Failed to save store customer order"
                );
            }

            console.log(
                "Store customer order saved:",
                data
            );

            setStoreOrderSaved(true);

            // Refresh customers because
            // a new customer may have been created.
            await fetchStoreCustomers();

            return true;

        } catch (error) {

            console.error(
                "Error saving store customer order:",
                error
            );

            alert(
                "Failed to save the store customer order. Please try again."
            );

            return false;

        } finally {

            setSavingStoreOrder(false);
        }
    };

    // ============================================================
    // GRAND TOTAL
    // ============================================================

    let grandTotal = 0;

    if (cart.length > 0) {

        // Resort customer
        grandTotal =
            cart.reduce(
                (sum, item) =>
                    sum +
                    Number(item.total),
                0
            );

        if (balance) {
            grandTotal +=
                Number(balance);
        }

    } else if (
        storeCart.length > 0
    ) {

        // Store customer
